// V3 — Consultation réelle + normalisation des sources.
// RÈGLE ABSOLUE : seule une page réellement téléchargée fait preuve. Aucun
// snippet de moteur de recherche n'est jamais une source. Trois canaux publics
// et gratuits, tous réellement consultés ici : site officiel du compte (HTML),
// API Recherche d'entreprises (INSEE Sirene), flux RSS Google News (presse).
// Le contenu externe est traité comme NON FIABLE : on le nettoie (scripts,
// styles), on le tronque, on ne le laisse jamais piloter la suite.
const ctx = $('V3 Prepare Context & Research Plan').first().json;
const siteResponse = $('V3 Fetch Official Site').first().json || {};
const registryResponse = $('V3 Fetch Public Registry').first().json || {};
const newsResponse = $('V3 Fetch Company News').first().json || {};

function simpleHash(str) {
  let h = 5381;
  const s = String(str == null ? '' : str);
  for (let i = 0; i < s.length; i += 1) h = ((h << 5) + h + s.charCodeAt(i)) | 0;
  return (h >>> 0).toString(16);
}

function canonicalUrl(url) {
  try {
    const u = new URL(url);
    u.search = '';
    u.hash = '';
    return u.toString();
  } catch (e) {
    return url;
  }
}

function domainOf(url) {
  try { return new URL(url).hostname.replace(/^www\./i, ''); } catch (e) { return null; }
}

function stripTags(html) {
  return String(html || '')
    .replace(/<script[\s\S]*?<\/script>/gi, ' ')
    .replace(/<style[\s\S]*?<\/style>/gi, ' ')
    .replace(/<noscript[\s\S]*?<\/noscript>/gi, ' ')
    .replace(/<[^>]+>/g, ' ')
    .replace(/&nbsp;/gi, ' ')
    .replace(/&amp;/gi, '&')
    .replace(/&quot;/gi, '"')
    .replace(/&#39;/gi, "'")
    .replace(/\s+/g, ' ')
    .trim();
}

function normalizeName(v) {
  return String(v || '')
    .toLowerCase()
    .normalize('NFD')
    .replace(/[̀-ͯ]/g, '')
    .replace(/[^a-z0-9]+/g, ' ')
    .trim();
}

const nowIso = new Date().toISOString();
const evidence = [];
const warnings = [];
// Diagnostic de recherche : trace toutes les URL candidates ET leur issue.
// Une URL non consultée avec succès y figure, mais NE PEUT PAS devenir une
// preuve citable — la séparation est explicite.
const diagnostic = [];

// ── Site officiel ────────────────────────────────────────────────────────────
const siteStatus = Number(siteResponse.statusCode || 0);
const siteBody = typeof siteResponse.body === 'string' ? siteResponse.body : '';
if (!ctx.hasSiteUrl) {
  warnings.push("Aucun site officiel public sur la fiche compte — recherche limitee au registre et a la presse.");
  diagnostic.push({ channel: 'official_site', url: null, consulted: false, reason: 'no_safe_url' });
} else if (siteStatus < 200 || siteStatus >= 300 || siteBody.length === 0) {
  warnings.push('Site officiel injoignable (statut ' + (siteStatus || 'inconnu') + ') — aucune preuve retenue.');
  diagnostic.push({ channel: 'official_site', url: ctx.siteUrl, consulted: false, reason: 'unreachable_' + (siteStatus || 0) });
} else {
  const text = stripTags(siteBody).slice(0, 14000);
  if (text.length < 120) {
    warnings.push('Site officiel recupere mais sans texte exploitable (rendu JS probable).');
    diagnostic.push({ channel: 'official_site', url: ctx.siteUrl, consulted: true, reason: 'no_extractable_text' });
  } else {
    evidence.push({
      kind: 'official_site',
      sourceKey: 'account_knowledge:site:' + simpleHash(canonicalUrl(ctx.siteUrl)),
      sourceType: 'official_site',
      sourceName: (ctx.canonical.name || 'Compte') + ' — site officiel',
      url: ctx.siteUrl,
      canonicalUrl: canonicalUrl(ctx.siteUrl),
      domain: domainOf(ctx.siteUrl),
      publishedAt: null,
      consultedAt: nowIso,
      reliability: 0.72,
      collectionMethod: 'scrape',
      fingerprint: simpleHash(text),
      excerpt: text.slice(0, 500),
      text: text,
      covers: "Discours officiel du compte : activite revendiquee, offres, implantations, clients cites, ambitions.",
    });
    diagnostic.push({ channel: 'official_site', url: ctx.siteUrl, consulted: true, reason: 'ok' });
  }
}

// ── Registre public (INSEE Sirene via data.gouv.fr) ──────────────────────────
const registryStatus = Number(registryResponse.statusCode || 0);
const registryBody = registryResponse.body || {};
const results = Array.isArray(registryBody.results) ? registryBody.results : [];
if (registryStatus < 200 || registryStatus >= 300) {
  warnings.push('Registre public injoignable (statut ' + (registryStatus || 'inconnu') + ').');
  diagnostic.push({ channel: 'registry', url: 'recherche-entreprises.api.gouv.fr', consulted: false, reason: 'unreachable_' + (registryStatus || 0) });
} else if (results.length === 0) {
  warnings.push('Aucune entite juridique trouvee au registre public pour ce nom.');
  diagnostic.push({ channel: 'registry', url: 'recherche-entreprises.api.gouv.fr', consulted: true, reason: 'no_match' });
} else {
  const target = normalizeName(ctx.canonical.legal_name || ctx.canonical.name);
  const scored = results.map((r) => {
    const candidate = normalizeName(r.nom_raison_sociale || r.nom_complet);
    let score = 0;
    if (candidate === target) score = 1;
    else if (candidate.startsWith(target) || target.startsWith(candidate)) score = 0.8;
    else if (candidate.includes(target) || target.includes(candidate)) score = 0.6;
    return { r: r, score: score };
  }).sort((a, b) => b.score - a.score);

  const best = scored[0];
  if (!best || best.score < 0.6) {
    warnings.push("Correspondance au registre public trop incertaine — aucune donnee legale retenue.");
    diagnostic.push({ channel: 'registry', url: 'recherche-entreprises.api.gouv.fr', consulted: true, reason: 'low_confidence_match' });
  } else {
    const r = best.r;
    const siege = r.siege || {};
    const tranche = String(r.tranche_effectif_salarie || siege.tranche_effectif_salarie || '');
    const TRANCHES = {
      '00': 0, '01': 2, '02': 4, '03': 7, '11': 15, '12': 35, '21': 75,
      '22': 150, '31': 225, '32': 375, '41': 750, '42': 1500, '51': 3500, '52': 7500,
    };
    evidence.push({
      kind: 'registry',
      sourceKey: 'account_knowledge:registry:' + r.siren,
      sourceType: 'regulatory_filing',
      sourceName: "Recherche d'entreprises (data.gouv.fr / INSEE Sirene)",
      url: 'https://recherche-entreprises.api.gouv.fr/search?q=' + r.siren,
      canonicalUrl: 'https://annuaire-entreprises.data.gouv.fr/entreprise/' + r.siren,
      domain: 'annuaire-entreprises.data.gouv.fr',
      publishedAt: r.date_mise_a_jour || null,
      consultedAt: nowIso,
      reliability: 0.97,
      collectionMethod: 'api',
      fingerprint: simpleHash(String(r.siren)),
      excerpt: ('SIREN ' + r.siren + ' — ' + (r.nom_raison_sociale || r.nom_complet)).slice(0, 500),
      covers: "Identite juridique officielle : raison sociale, SIREN, code NAF, siege, tranche d'effectif.",
      registry: {
        siren: r.siren || null,
        legalName: r.nom_raison_sociale || r.nom_complet || null,
        nafCode: r.activite_principale || null,
        activityLabel: r.libelle_activite_principale || null,
        hqLocation: [siege.libelle_commune, siege.code_postal].filter(Boolean).join(' ') || null,
        employeeCount: Object.prototype.hasOwnProperty.call(TRANCHES, tranche) ? TRANCHES[tranche] : null,
        employeeCountIsEstimate: true,
        matchScore: best.score,
      },
      text: JSON.stringify({
        siren: r.siren,
        raison_sociale: r.nom_raison_sociale || r.nom_complet,
        activite_principale: r.activite_principale,
        libelle_activite_principale: r.libelle_activite_principale,
        siege: { commune: siege.libelle_commune, code_postal: siege.code_postal },
        tranche_effectif_salarie: tranche,
      }),
    });
    diagnostic.push({ channel: 'registry', url: 'recherche-entreprises.api.gouv.fr', consulted: true, reason: 'ok', matchScore: best.score });
  }
}

// ── Presse (flux RSS Google News) ────────────────────────────────────────────
// Chaque <item> réellement présent dans le flux devient une preuve de presse
// distincte, avec sa propre URL canonique. Le flux lui-même n'est jamais cité.
const newsStatus = Number(newsResponse.statusCode || 0);
const newsBody = typeof newsResponse.body === 'string' ? newsResponse.body : '';
if (!ctx.hasNewsQuery) {
  diagnostic.push({ channel: 'press', url: null, consulted: false, reason: 'no_query' });
} else if (newsStatus < 200 || newsStatus >= 300 || newsBody.length === 0) {
  warnings.push('Flux presse injoignable (statut ' + (newsStatus || 'inconnu') + ').');
  diagnostic.push({ channel: 'press', url: 'news.google.com/rss', consulted: false, reason: 'unreachable_' + (newsStatus || 0) });
} else {
  const items = newsBody.split(/<item>/i).slice(1).map((chunk) => chunk.split(/<\/item>/i)[0]);
  function tag(chunk, name) {
    const re = new RegExp('<' + name + '[^>]*>([\\s\\S]*?)<\\/' + name + '>', 'i');
    const m = chunk.match(re);
    if (!m) return null;
    let v = m[1];
    const cdata = v.match(/<!\[CDATA\[([\s\S]*?)\]\]>/i);
    if (cdata) v = cdata[1];
    return stripTags(v).slice(0, 600) || null;
  }
  let kept = 0;
  const seenLinks = new Set();
  for (const chunk of items) {
    if (kept >= 5) break;
    const title = tag(chunk, 'title');
    const link = tag(chunk, 'link');
    const pubDate = tag(chunk, 'pubDate');
    if (!title || !link) continue;
    const cu = canonicalUrl(link);
    if (seenLinks.has(cu)) continue;
    seenLinks.add(cu);
    let publishedAtIso = null;
    if (pubDate) {
      const d = new Date(pubDate);
      if (!Number.isNaN(d.getTime())) publishedAtIso = d.toISOString();
    }
    evidence.push({
      kind: 'press',
      sourceKey: 'account_knowledge:press:' + simpleHash(cu),
      sourceType: 'press_article',
      sourceName: (domainOf(link) || 'Presse') + ' — ' + title.slice(0, 120),
      url: link,
      canonicalUrl: cu,
      domain: domainOf(link),
      publishedAt: publishedAtIso,
      consultedAt: nowIso,
      reliability: 0.5,
      collectionMethod: 'rss',
      fingerprint: simpleHash(cu),
      excerpt: title.slice(0, 500),
      text: title,
      covers: "Actualite recente citant le compte (titre de presse) — a corroborer, source editoriale.",
    });
    kept += 1;
  }
  diagnostic.push({ channel: 'press', url: 'news.google.com/rss', consulted: true, reason: 'ok', itemsKept: kept });
  if (kept === 0) warnings.push('Flux presse consulte mais aucun article exploitable pour ce compte.');
}

return [{ json: { externalEvidence: evidence, researchWarnings: warnings, researchDiagnostic: diagnostic, researchPerformed: true } }];

// V3 — Constitution du lot de sources à persister (upsert idempotent).
// Relit le contexte et les preuves via des nœuds nommés (jamais l'item reçu :
// il peut être vide côté HTTP). La source interne « base relationnelle KREDO »
