    const seen = new Set();
    tn.significant_signal_ids.forEach((idv, i) => {
      if (!UUID.test(String(idv))) errors.push('$.trends_and_news.significant_signal_ids[' + i + '] : UUID invalide');
      else if (seen.has(idv)) errors.push('$.trends_and_news.significant_signal_ids[' + i + '] : signal en double');
      else seen.add(idv);
    });
  }
}

if (!isObj(ak.source_coverage)) errors.push('$.source_coverage : objet requis');
if (!isIso(ak.generated_at)) errors.push('$.generated_at : date ISO requise');

// ── Croisement claims <-> verification_results ──────────────────────────────
function collectV3Claims(c) {
  const out = [];
  function pn(cl, path) { if (cl !== null && cl !== undefined) out.push({ path: path, claim: cl }); }
  function pa2(cls, base) { (cls || []).forEach((cl, i) => out.push({ path: base + '[' + i + ']', claim: cl })); }
  pn(c.account_summary, '$.account_summary');
  const i = c.identity;
  pn(i.company_name, '$.identity.company_name'); pn(i.legal_name, '$.identity.legal_name');
  pn(i.primary_activity, '$.identity.primary_activity'); pn(i.headquarters, '$.identity.headquarters');
  pn(i.sector, '$.identity.sector'); pn(i.business_segment, '$.identity.business_segment');
  pn(i.revenue, '$.identity.revenue'); pn(i.employee_count, '$.identity.employee_count');
  pa2(i.geographic_reach, '$.identity.geographic_reach');
  const m = c.market_positioning;
  pn(m.account_positioning, '$.market_positioning.account_positioning');
  pn(m.competitive_environment, '$.market_positioning.competitive_environment');
  pa2(m.direct_competitors, '$.market_positioning.direct_competitors');
  pa2(m.competitive_advantages, '$.market_positioning.competitive_advantages');
  pa2(m.opportunities, '$.market_positioning.opportunities');
  pa2(m.threats, '$.market_positioning.threats');
  const p = m.policy_and_ambitions; const pb = '$.market_positioning.policy_and_ambitions';
  pn(p.purpose, pb + '.purpose'); pn(p.philosophy, pb + '.philosophy');
  pa2(p.culture, pb + '.culture'); pa2(p.public_statements, pb + '.public_statements');
  pa2(p.ambitions, pb + '.ambitions'); pa2(p.strategic_axes, pb + '.strategic_axes');
  pa2(p.leadership_posture, pb + '.leadership_posture'); pn(p.claimed_identity, pb + '.claimed_identity');
  const o = c.offers_and_customers;
  pn(o.core_business, '$.offers_and_customers.core_business');
  pa2(o.offers, '$.offers_and_customers.offers'); pa2(o.covered_domains, '$.offers_and_customers.covered_domains');
  pa2(o.services, '$.offers_and_customers.services'); pa2(o.service_models, '$.offers_and_customers.service_models');
  pa2(o.complementary_activities, '$.offers_and_customers.complementary_activities');
  pa2(o.uncovered_activities, '$.offers_and_customers.uncovered_activities');
  pn(o.customer_profile, '$.offers_and_customers.customer_profile');
  pa2(o.customer_segments, '$.offers_and_customers.customer_segments');
  pa2(o.segment_weights, '$.offers_and_customers.segment_weights');
  pa2(o.behavioral_trends, '$.offers_and_customers.behavioral_trends');
  pa2(o.unmet_needs, '$.offers_and_customers.unmet_needs');
  const v = c.value_chain;
  pn(v.description, '$.value_chain.description'); pn(v.value_proposition, '$.value_chain.value_proposition');
  pa2(v.key_links, '$.value_chain.key_links'); pa2(v.critical_partners_or_suppliers, '$.value_chain.critical_partners_or_suppliers');
  pa2(v.dependencies, '$.value_chain.dependencies'); pa2(v.vulnerabilities, '$.value_chain.vulnerabilities');
  pn(v.end_customer_relationship, '$.value_chain.end_customer_relationship');
  const r = c.regulatory_environment;
  pa2(r.current_regulations, '$.regulatory_environment.current_regulations');
  pa2(r.required_certifications, '$.regulatory_environment.required_certifications');
  pa2(r.compliance_risks, '$.regulatory_environment.compliance_risks');
  pn(c.trends_and_news.analysis, '$.trends_and_news.analysis');
  return out;
}

if (errors.length === 0 && Array.isArray(ak.verification_results)) {
  const entries = collectV3Claims(ak);
  const claimByPath = new Map(entries.map((e) => [e.path, e.claim]));
  const resultByPath = new Map();
  ak.verification_results.forEach((res, i) => {
    const path = '$.verification_results[' + i + ']';
    if (!isObj(res)) { errors.push(path + ' : objet requis'); return; }
    keys(res, ['claim_path', 'verdict', 'checked_at', 'supporting_source_refs', 'contradicting_source_refs', 'rationale'], path);
    if (typeof res.claim_path !== 'string' || !claimByPath.has(res.claim_path)) { errors.push(path + '.claim_path : sans claim correspondant'); return; }
    if (resultByPath.has(res.claim_path)) { errors.push(path + '.claim_path : resultat en double'); return; }
    resultByPath.set(res.claim_path, res);
    if (res.verdict !== 'confirmed') errors.push(path + '.verdict : un claim publie doit etre confirme');
    if (!Array.isArray(res.supporting_source_refs) || res.supporting_source_refs.length === 0) errors.push(path + '.supporting_source_refs : au moins une source de confirmation');
    if (Array.isArray(res.contradicting_source_refs) && res.contradicting_source_refs.length > 0) errors.push(path + '.contradicting_source_refs : interdit pour un confirmed');
    if (!isIso(res.checked_at)) errors.push(path + '.checked_at : date ISO requise');
    // Invariant Lot 3 : supporting ⊆ source_refs du claim.
    const claimObj = claimByPath.get(res.claim_path);
    const refs = new Set((claimObj && claimObj.source_refs) || []);
    (res.supporting_source_refs || []).forEach((r) => { if (!refs.has(r)) errors.push(path + '.supporting_source_refs : ' + r + ' absent des source_refs du claim'); });
  });
  for (const e of entries) {
    if (!resultByPath.has(e.path)) errors.push('$.verification_results : resultat manquant pour ' + e.path);
  }
} else if (!Array.isArray(ak.verification_results)) {
  errors.push('$.verification_results : tableau requis');
}

if (errors.length > 0) {
  throw new Error('Artefact account_knowledge V3 REJETE (' + errors.length + ') : ' + errors.slice(0, 12).join(' | '));
}

// ── qa_flags (informatif — les manquements bloquants ont deja fait echouer) ──
const cov = ak.source_coverage;
const qaFlags = [];
qaFlags.push({ check: 'seven_sections_in_order', passed: true, detail: 'account_summary → identity → market_positioning → offers_and_customers → value_chain → regulatory_environment → trends_and_news' });
qaFlags.push({ check: 'all_claims_verified_confirmed', passed: true, detail: (ak.verification_results || []).length + ' affirmation(s) publiee(s), toutes confirmees independamment' });
qaFlags.push({ check: 'independent_verification_separate_call', passed: true, detail: 'generation et verification = deux invocations LLM distinctes' });
qaFlags.push({ check: 'all_claims_sourced', passed: cov.passed, detail: cov.sourced_claims + '/' + cov.displayed_claims + ' affirmations sourcees' });
qaFlags.push({ check: 'dynamic_left_to_engine', passed: ak.identity.dynamic === null, detail: 'indicateur de dynamique calcule hors modele' });
qaFlags.push({ check: 'external_research_performed', passed: !!data.researchPerformed, detail: (data.externalEvidence || []).length + ' preuve(s) externe(s) reellement consultee(s)' });
const folioSources = (data.catalogue || []).filter((c) => c.type === 'folio_legacy');
qaFlags.push({ check: 'no_folio_source', passed: folioSources.length === 0, detail: folioSources.length === 0 ? 'OK' : folioSources.length + ' source folio_legacy au catalogue' });
qaFlags.push({ check: 'signals_capped_three', passed: (ak.trends_and_news.significant_signal_ids || []).length <= 3, detail: (ak.trends_and_news.significant_signal_ids || []).length + ' signal(aux) significatif(s)' });
const droppedCount = (data.droppedClaims || []).length;
qaFlags.push({ check: 'unpublishable_claims_removed', passed: true, detail: droppedCount + ' affirmation(s) retiree(s) (contredite / preuve insuffisante / non verifiee)' });
for (const w of (data.researchWarnings || [])) qaFlags.push({ check: 'research_warning', passed: true, detail: w });

return [{ json: { ...data, qaFlags: qaFlags } }];

// V3 — Propositions d'enrichissement (SEUL chemin d'écriture vers les données
// canoniques du compte). Ce workflow n'écrit JAMAIS dans `companies` : une
// donnée canonique ne change qu'après validation humaine
// (validate_and_apply_enrichment_proposals). Espace de nommage partagé avec
// intel-010-refresh (`account_scan:{companyId}:{attribut}`) : la clé identifie
// l'attribut, pas le workflow producteur.
const data = $('V3 Validate Artifact').first().json;
const activeProposals = $input.all().map((i) => i.json).filter((r) => r && r.proposal_key);
const sourceIdByKey = new Map((data.sourceIdByKey || []).map((r) => [r.source_key, r.id]));

function simpleHash(str) {
  let h = 5381;
  const s = String(str == null ? '' : str);
  for (let i = 0; i < s.length; i += 1) h = ((h << 5) + h + s.charCodeAt(i)) | 0;
  return (h >>> 0).toString(16);
}
function norm(v) {
  if (v === null || v === undefined) return null;
  const t = String(v).replace(/\s+/g, ' ').trim();
  return t.length > 0 ? t.toLowerCase() : null;
}

const registryEvidence = (data.externalEvidence || []).find((e) => e.kind === 'registry');
const siteEvidence = (data.externalEvidence || []).find((e) => e.kind === 'official_site');
const canonical = data.canonical;
const candidates = [];
const warnings = [];

function propose(opts) {
  const proposed = norm(opts.value);
  if (!proposed) return;
  if (norm(opts.currentValue) === proposed) return;
  candidates.push({
    proposal_key: 'account_scan:' + data.companyId + ':' + opts.attribute,
    target_type: 'company',
    target_id: data.companyId,
    attribute_name: opts.attribute,
    proposed_value: String(opts.value).trim(),
    normalized_value: proposed,
    normalized_value_hash: simpleHash(proposed),
    initial_snapshot: { current: opts.currentValue === undefined ? null : opts.currentValue },
    primary_source_id: sourceIdByKey.get(opts.sourceKey) || null,
    origin: 'external',
    confidence_score: opts.confidence,
    justification: opts.justification,
    status: opts.confidence < 0.45 ? 'needs_review' : 'proposed',
    run_id: data.runId,
    workspace_id: data.workspaceId,
  });
}

if (registryEvidence && registryEvidence.registry) {
  const r = registryEvidence.registry;
  const key = registryEvidence.sourceKey;
  propose({ attribute: 'legal_name', value: r.legalName, sourceKey: key, confidence: 0.95, justification: 'Raison sociale au registre public (SIREN ' + r.siren + ').', currentValue: canonical.legal_name });
  propose({ attribute: 'siren', value: r.siren, sourceKey: key, confidence: 0.95, justification: 'SIREN issu du registre public.', currentValue: null });
  propose({ attribute: 'naf_code', value: r.nafCode, sourceKey: key, confidence: 0.9, justification: 'Code NAF declare : ' + (r.activityLabel || r.nafCode) + '.', currentValue: null });
  propose({ attribute: 'hq_location', value: r.hqLocation, sourceKey: key, confidence: 0.85, justification: 'Commune du siege au registre public.', currentValue: canonical.hq_location });
  if (r.employeeCount !== null) {
    propose({ attribute: 'employee_count', value: r.employeeCount, sourceKey: key, confidence: 0.55, justification: "Estimation issue de la tranche d'effectif INSEE (point median de la tranche).", currentValue: canonical.employee_count });
  }
  if (r.activityLabel) {
    propose({ attribute: 'description', value: r.activityLabel, sourceKey: key, confidence: 0.6, justification: "Libelle de l'activite principale declaree au registre public.", currentValue: canonical.description });
  }
} else {
  warnings.push('Aucune entite juridique resolue : aucune proposition sur les donnees canoniques legales.');
}

if (siteEvidence && !canonical.website) {
  propose({ attribute: 'website', value: siteEvidence.canonicalUrl || siteEvidence.url, sourceKey: siteEvidence.sourceKey, confidence: 0.7, justification: 'Site officiel effectivement recupere.', currentValue: canonical.website });
}

// Réconciliation idempotente.
const byKey = new Map(activeProposals.map((p) => [p.proposal_key, p]));
const untouched = new Set(activeProposals.filter((p) => ['validated', 'conflicting'].includes(p.status)).map((p) => p.proposal_key));

const toInsert = [];
const staleIdsToDelete = [];
for (const c of candidates) {
  if (untouched.has(c.proposal_key)) {
    warnings.push('Proposition deja decidee ou en conflit pour "' + c.attribute_name + '" — non regeneree.');
    continue;
  }
  const existing = byKey.get(c.proposal_key);
  if (existing && ['proposed', 'needs_review'].includes(existing.status)) {
    if (norm(existing.proposed_value) === c.normalized_value) continue;
    staleIdsToDelete.push(existing.id);
  }
  toInsert.push(c);
}

return [{
  json: {
    ...data,
    proposalWarnings: warnings,
    toInsert: toInsert,
    staleIdsToDelete: staleIdsToDelete,
    proposalsCount: toInsert.length,
  }
}];

// V3 — Aucune proposition à écrire. Un item est renvoyé quand même : sans lui,
// le nœud suivant ne serait pas exécuté et le run resterait bloqué en "running".
return [{ json: { proposalsInserted: 0 } }];

// V3 — Préparation du payload de callback (succès). Relit tout depuis
// "V3 Build Enrichment Proposals" (jamais une branche IF qui a pu ne pas
// s'exécuter). Contrat identique aux autres workflows : signature HMAC en aval.
const data = $('V3 Build Enrichment Proposals').first().json;
const companyName = (data.canonical && data.canonical.name) || 'Compte';
const ak = data.accountKnowledge;

const sourceRefs = Array.from(new Set(data.usedSourceIds || [])).map((id) => ({
  entityType: 'intelligence_source',
  entityId: id,
  label: (data.catalogue || []).find((c) => c.source_id === id) ? ((data.catalogue || []).find((c) => c.source_id === id).name || 'Source') : 'Source',
}));

const qaFlags = [
  ...(data.qaFlags || []),
  ...(data.proposalWarnings || []).map((w) => ({ check: 'proposal_warning', passed: true, detail: w })),
  { check: 'enrichment_proposals_written', passed: true, detail: (data.proposalsCount || 0) + " proposition(s) d'enrichissement" },
];

const draftUsage = data.draftLlmUsage || {};
const verifyUsage = data.verifyLlmUsage || {};
function sumTok(a, b) {
  if (a === null || a === undefined) a = 0;
  if (b === null || b === undefined) b = 0;
  const s = a + b;
  return s > 0 ? s : null;
}

const startedAt = $('Validate Entity').first().json.startedAtMs || null;

const callbackBody = {
  n8nExecutionId: $execution.id,
  n8nWorkflowId: $workflow.id,
  runId: data.runId,
  phase: 1,
  resultType: 'account_knowledge',
  status: 'succeeded',
  contentJson: ak,
  contentText: [
    '# Connaissance entreprise — ' + companyName,
    ak.account_summary ? ak.account_summary.text : '',
  ].filter(Boolean).join('\n\n'),
  title: 'Connaissance entreprise — ' + companyName,
  modelProvider: 'anthropic',
  modelUsed: draftUsage.model || 'claude-sonnet-5',
  tokensInput: sumTok(draftUsage.inputTokens, verifyUsage.inputTokens),
  tokensOutput: sumTok(draftUsage.outputTokens, verifyUsage.outputTokens),
  durationMs: startedAt ? (Date.now() - startedAt) : null,
  contextSnapshot: {
    schemaVersion: 3,
    canonical: data.canonical,
    researchPlan: data.researchPlan,
    researchDiagnostic: data.researchDiagnostic,
    researchPerformed: data.researchPerformed,
    catalogue: (data.catalogue || []).map(({ content, ...rest }) => rest),
    droppedClaims: data.droppedClaims || [],
    publishedClaimCount: data.publishedClaimCount || 0,
    dataCutoffAt: data.dataCutoffAt,
  },
  sourceRefs: sourceRefs,
  qaFlags: qaFlags,
};

return [{ json: { callbackUrl: data.callbackUrl, rawBody: JSON.stringify(callbackBody) } }];
